-- You can (and should!!) split this configuration into multiple files
-- Create your files separately and then require them like this:
-- require("myColors")

-- Liquid Glass blur (hyprglass, installed via Nix: pkgs.hyprglass).
-- Must load BEFORE any hl.config() call that uses plugin keys, so it lives
-- at the top of the config. hyprglass-path.lua is Nix-generated with the
-- exact store path (see home.nix); the fallbacks cover sessions where the
-- HM file isn't present yet.
-- Emergency bypass: set HYPR_NO_GLASS=1 to skip the plugin entirely.
local no_glass = false
pcall(function() no_glass = os.getenv("HYPR_NO_GLASS") == "1" end)
if not no_glass then
    -- Single load path. hyprglass-path.lua is Nix-generated with the exact
    -- store path (see home.nix) and is always present (same dir as this
    -- file, managed by home-manager).
    -- Do NOT add fallback loads (HYPR_PLUGIN_DIR, ~/.nix-profile, ...):
    -- hl.plugin loads are queued and applied later, so hl.plugin.hyprglass
    -- is still nil here and any `if not hl.plugin.hyprglass` guard ALWAYS
    -- fires, queueing the same .so a second time under a different path
    -- string. Hyprland then initialises the plugin twice and segfaults in
    -- CPluginSystem::updateConfigPlugins (back to the login screen).
    pcall(require, "hyprglass-path")
end

if not no_glass and hl.plugin.hyprglass then
    local hg = hl.plugin.hyprglass

    hg.config({
        default_theme = "dark",
        default_preset = "strong",
        -- Glass replaces Hyprland blur per-window (sets noblur itself),
        -- so the cached-blur optimization no longer hides static glass.
        manage_window_blur = true,
        layers = { enabled = true },
    })

    -- Max-strength custom preset: inherits the punchiest built-in ("glass")
    -- and pushes every effect slider to the top of its range.
    hg.preset("strong", {
        inherits = "glass",
        blur_strength = 0.6,
        blur_iterations = 0.2,
        refraction_strength = 1.2,
        chromatic_aberration = 0.3,
        fresnel_strength = 0.0,
        specular_strength = 1.5,
        edge_thickness = 0.1,
        lens_distortion = 1.15,
        glass_opacity = 1.0,
    })

    -- Layer surfaces: each call whitelists the namespace and configures it.
    hg.layer("waybar", { preset = "strong", mask_threshold = 0.05 })
    hg.layer("nwg-dock", { preset = "strong", mask_threshold = 0.05 })
    hg.layer("nwg-dock-hyprland", { preset = "strong", mask_threshold = 0.05 })
end

