-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Hyprglass per-window overrides (tags).
-- NOTE: no fullscreen rule on purpose. A `match fullscreen -> tag` rule
-- applies hyprglass_disabled on entering fullscreen but the dynamic tag is
-- never removed on exit, so glass stays off permanently (sticky tags were
-- observed on tiled kitty/Zed windows). Upstream agrees: keep glass on
-- fullscreen (fixed plugin-side in v0.8+). Class-based rules like mpv below
-- are safe (matched once at open, never stale).
if hl.plugin.hyprglass then
    hl.window_rule({
        name  = "hyprglass-no-mpv",
        match = { class = "mpv" },
        tag   = "+hyprglass_disabled",
    })
    -- TEMPORARY one-shot (already applied 2026-10-08, rule since removed):
    -- stale hyprglass_disabled dynamic tags were stripped via
    -- `tag = "-hyprglass_disabled"` on `match class .*` + reload.
end

-- Backdrop blur for waybar (not possible in hyprlang)
hl.layer_rule({
	name = "blur-waybar",
	match = { namespace = "waybar" },
	blur = true,
	ignore_alpha = 0,
})

hl.layer_rule({
	name = "blur-dock",
	match = { namespace = "nwg-dock" },
	blur = true,
	ignore_alpha = 0,
})
